window.ScripturaLexicons.BDAG_PART_0209 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-01\" data-source=\"BDAG\" data-search=\"κουμι remissão lexical veja κουμ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κουμι</td><td>remissão lexical</td><td>veja κουμ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-02\" data-source=\"BDAG\" data-search=\"κουστωδία, ας, ἡ substantivo feminino; empréstimo latino guarda; destacamento de soldados BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κουστωδία, ας, ἡ</td><td>substantivo feminino; empréstimo latino</td><td>guarda; destacamento de soldados</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-03\" data-source=\"BDAG\" data-search=\"κουφίζω verbo aliviar; tornar mais leve; descarregar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κουφίζω</td><td>verbo</td><td>aliviar; tornar mais leve; descarregar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-04\" data-source=\"BDAG\" data-search=\"κούφισμα, ατος, τό substantivo neutro alívio; diminuição de um fardo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κούφισμα, ατος, τό</td><td>substantivo neutro</td><td>alívio; diminuição de um fardo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-05\" data-source=\"BDAG\" data-search=\"κόφινος, ου, ὁ substantivo masculino cesto; balaio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόφινος, ου, ὁ</td><td>substantivo masculino</td><td>cesto; balaio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-06\" data-source=\"BDAG\" data-search=\"κράβαττος, ου, ὁ substantivo masculino catre; esteira; leito rudimentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κράβαττος, ου, ὁ</td><td>substantivo masculino</td><td>catre; esteira; leito rudimentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-07\" data-source=\"BDAG\" data-search=\"κράζω verbo gritar; clamar; bradar; proclamar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κράζω</td><td>verbo</td><td>gritar; clamar; bradar; proclamar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-08\" data-source=\"BDAG\" data-search=\"κραιπάλη, ης, ἡ substantivo feminino bebedeira; dissipação; ressaca BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κραιπάλη, ης, ἡ</td><td>substantivo feminino</td><td>bebedeira; dissipação; ressaca</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-09\" data-source=\"BDAG\" data-search=\"κρανίον, ου, τό substantivo neutro crânio; caveira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρανίον, ου, τό</td><td>substantivo neutro</td><td>crânio; caveira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-10\" data-source=\"BDAG\" data-search=\"κράσπεδον, ου, τό substantivo neutro bainha; borda; franja ritual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κράσπεδον, ου, τό</td><td>substantivo neutro</td><td>bainha; borda; franja ritual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-11\" data-source=\"BDAG\" data-search=\"κραταιός, ά, όν adjetivo poderoso; forte; vigoroso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κραταιός, ά, όν</td><td>adjetivo</td><td>poderoso; forte; vigoroso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-12\" data-source=\"BDAG\" data-search=\"κραταιόω verbo fortalecer; tornar-se forte; adquirir vigor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κραταιόω</td><td>verbo</td><td>fortalecer; tornar-se forte; adquirir vigor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-13\" data-source=\"BDAG\" data-search=\"κρατέω verbo alcançar; segurar; prender; sustentar; reter; apegar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρατέω</td><td>verbo</td><td>alcançar; segurar; prender; sustentar; reter; apegar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-14\" data-source=\"BDAG\" data-search=\"κράτιστος, η, ον adjetivo superlativo; tratamento honorífico excelentíssimo; muito nobre; ilustre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κράτιστος, η, ον</td><td>adjetivo superlativo; tratamento honorífico</td><td>excelentíssimo; muito nobre; ilustre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-15\" data-source=\"BDAG\" data-search=\"κράτος, ους, τό substantivo neutro força; poder; ato poderoso; domínio; soberania BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κράτος, ους, τό</td><td>substantivo neutro</td><td>força; poder; ato poderoso; domínio; soberania</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-16\" data-source=\"BDAG\" data-search=\"κραυγάζω verbo bradar; gritar; clamar em voz alta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κραυγάζω</td><td>verbo</td><td>bradar; gritar; clamar em voz alta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-17\" data-source=\"BDAG\" data-search=\"κραυγή, ῆς, ἡ substantivo feminino grito; clamor; gritaria; lamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κραυγή, ῆς, ἡ</td><td>substantivo feminino</td><td>grito; clamor; gritaria; lamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-18\" data-source=\"BDAG\" data-search=\"κρέας, κρέως substantivo neutro carne; alimento de origem animal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρέας, κρέως</td><td>substantivo neutro</td><td>carne; alimento de origem animal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-19\" data-source=\"BDAG\" data-search=\"κρείσσων remissão lexical veja κρείττων BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρείσσων</td><td>remissão lexical</td><td>veja κρείττων</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0209-20\" data-source=\"BDAG\" data-search=\"κρείττων, ον, adjetivo comparativo superior; melhor; mais vantajoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρείττων, ον,</td><td>adjetivo comparativo</td><td>superior; melhor; mais vantajoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0209-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουμι</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κουμι</span>: veja <span class=\"greek\">κουμ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουστωδία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino; empréstimo latino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κουστωδία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (POxy 294, 20 [22 d.C.]; PRyl 189, 2; BGU 341, 3; veja Hahn 233, 6; 234, 7 com bibliografia.—Empréstimo latino, custodia, também no hebraico rabínico): grupo de soldados em serviço de vigilância, guarda composta por soldados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.66\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:66</a>; 28:11. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">κουστωδίαν</span>, tomar uma guarda, 27:65.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουφίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κουφίζω</span> (<span class=\"greek\">κοῦφος</span>, ‘leve’; veja também o verbete seguinte): imperfeito <span class=\"greek\">ἐκούφιζον</span>; futuro <span class=\"greek\">κουφιῶ</span>; aoristo <span class=\"greek\">ἐκούφισα</span>; infinitivo aoristo passivo <span class=\"greek\">κουφισθῆναι</span> (todas as formas na LXX) (Hes. e outros): diminuir o peso de alguma coisa, tornar leve, aliviar (assim autores trágicos; Dio Chrys. 80 [30], 40; inscrições, papiros, LXX; Jos., Bell. 2, 96, Ant. 18, 149); com <span class=\"greek\">τὶ</span>, alguma coisa (1 Km 6:5): <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῖον</span>, aliviar o peso do navio lançando fora a carga, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:38</a> (Polyb. 20, 5, 11; Jon 1:5; GMiles/GTrompf, HTR 69, ’76, 259–67, com referência à descrição de naufrágio em Antiphon [o orador], The Murder of Herodes).—New Docs 2, 74. DELG s.v. <span class=\"greek\">κοῦφος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κούφισμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κούφισμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja o verbete anterior; Eur., Phoen. 860; Plut., Mor. 114c): aquilo que torna algo menos pesado; alívio, atenuação, sobre a prática de dar esmolas: <span class=\"greek\">κ</span>. <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">γίνεται</span>, alivia o fardo do pecado, 2 Cl 16:4 (seguindo 1 Esdr 8:84 <span class=\"greek\">σύ</span>, <span class=\"greek\">κύριε</span>, <span class=\"greek\">ἐκούφισας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">ἡμῶν</span>, tu, Senhor, aliviaste nossos pecados; compare 2 Esdr 9:13).—DELG s.v. <span class=\"greek\">κοῦφος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόφινος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόφινος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aristoph., X. e outros; inscrições, papiros; Judg 6:19 B; Ps 80:7; ParJer; empréstimo para o latim, veja Juvenal abaixo): cesto; no NT, provavelmente um cesto grande e pesado, talvez de tamanhos diversos, destinado ao transporte de objetos (veja Juvenal 3, 14; 6, 542; RHorn, Lutheran Quarterly 1, ’49, 301; FHort, JTS 10, 1909, 567ff; Artem. 2, 24; Jos., Bell. 3, 95), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:13</a>. Junto de <span class=\"greek\">σφυρίς</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:20</a>; compare sobre isso APF 6, 1920, 220 no. 8, 4f [III a.C.] <span class=\"greek\">Φίλωνι</span> <span class=\"greek\">κόφινοι</span> <span class=\"greek\">β</span>´, <span class=\"greek\">Πτολεμαίῳ</span> <span class=\"greek\">σφυρίδιον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:19</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">κοπρίων</span>, cesto de estrume, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:8</a> D (Nicol. Dam.: 90 Fgm. 66, 13 Jac. <span class=\"greek\">κόπρον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κοφίνῳ</span>).—B. 623. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράβαττος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κράβαττος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (manuscritos e editores também apresentam <span class=\"greek\">κράβατος</span>, <span class=\"greek\">κράββατος</span>, <span class=\"greek\">κρέβαττος</span> [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:3</a>, variante de leitura]; empréstimo de origem incerta, encontrado também no hebraico rabínico e de aparecimento tardio [Phryn. 62 Lob.]. Segundo Pollux 10, 35, na forma <span class=\"greek\">κράββατος</span>, nos poetas cômicos Rhinto [III a.C.] e Crito [II a.C.]; também TestJob [manuscrito P, <span class=\"greek\">κράβαττ</span>-SV]; também Epict 1, 24, 14; Aesop, Fab. 413 H.; PLond II, 191, 16 p. 265 [II d.C.] <span class=\"greek\">κράββατος</span>. Óstraco em Mélanges Nicole 1905 p. 184 = Sb 4292, 9 e Moeris p. 58; 354 <span class=\"greek\">κράβατος</span>. Também ocorre a forma <span class=\"greek\">κράβακτος</span>: PTebt 406, 19.—Am 3:12 Aq. Sobre a forma da palavra, veja B-D-F §42, 4; W-S. §5, 26a n.; Mlt. 244; Mlt-H. 102 [§41d]; Rob. 119; 213): colchão, catre, leito dos pobres, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:4</a>; 6:55. Junto de <span class=\"greek\">κλινάριον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:15</a>. <span class=\"greek\">αἴρειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., carregar o catre, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:9</a>, 11f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:8</a>–11, 12, variante de leitura (compare Lucian, Philopseud. 11 <span class=\"greek\">ὁ</span> <span class=\"greek\">Μίδας</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἀράμενος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σκίμποδα</span>, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐκεκόμιστο</span>, <span class=\"greek\">ᾤχετο</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀγρὸν</span> <span class=\"greek\">ἀπιών</span>, ‘o próprio Midas tomou o catre sobre o qual havia sido levado, saiu e voltou ao campo [isto é, ao trabalho de viticultura]’). <span class=\"greek\">κατακεῖσθαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κραβάττου</span>, estar deitado no leito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:33</a>. JKramer, APF 41/2, ’95.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κράζω</span> (desde Aeschyl.; também Aesop, Fab. 252 P., de um galo): particípio neutro <span class=\"greek\">κρᾶζον</span> (B-D-F §13; W-S. §6, 2; Rob. 231); imperfeito <span class=\"greek\">ἔκραζον</span>; futuro <span class=\"greek\">κράξω</span> e <span class=\"greek\">κεκράξομαι</span> (B-D-F §77; W-S. §13, 2; Mlt. 154; Rob. 361); 1º aoristo <span class=\"greek\">ἔκραξα</span> e <span class=\"greek\">ἐκέκραξα</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:21</a>; veja B-D-F §75; W-S. §13, 2; 10 nota 10; Mlt. 147; compare Mlt-H. 244); perfeito <span class=\"greek\">κέκραγα</span>; mais-que-perfeito, 3ª pessoa do singular, <span class=\"greek\">ἐκεκράγει</span> (3 Macc 5:23, variante de leitura).</p>\n<p class=\"entry-text\">① Produzir um grito veemente; gritar, berrar, soltar brados, quando se emitem gritos altos sem palavras inteligíveis (compare Hippol., Ref. 4, 28, 3 e 6): de pessoas com perturbação mental, epilépticos ou dos espíritos malignos que nelas habitam, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:5</a>; 9:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:41</a>, variante de leitura; 9:39. Sobre o grito de morte de Jesus na cruz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:39</a>, variante de leitura. Sobre o grito de uma mulher em trabalho de parto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:2</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φόβου</span>, gritar de medo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:26</a>. <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span>, clamar em alta voz, 27:50; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:26</a>, variante de leitura (em lugar de <span class=\"greek\">φωνῆσαν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.57\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:57</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:3a</a>, compare 3b.</p>\n<p class=\"entry-text\">② Comunicar algo em voz alta; chamar, clamar, gritar.</p>\n<p class=\"entry-text\">ⓐ Literalmente: <span class=\"greek\">κράζει</span> <span class=\"greek\">ὄπισθεν</span> <span class=\"greek\">ἡμῶν</span>, ela grita atrás de nós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:23</a>. Com <span class=\"greek\">τὶ</span>, alguma coisa, dito de uma multidão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:32</a>. <span class=\"greek\">φωνὴν</span> <span class=\"greek\">κ</span>., clamar algo em voz alta, 24:21. Seguido de discurso direto (B-D-F §397, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:48</a>; 11:9; 15:13f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:13</a>, variante de leitura (veja <span class=\"greek\">κραυγάζω</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:34</a>; 21:28, 36; 23:6. Com <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span> e discurso direto subsequente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.60\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:60</a>. Também <span class=\"greek\">ἐν</span> <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:15</a>. Empregado com <span class=\"greek\">λέγειν</span> (B-D-F §420, 2 apêndice) para falar em voz alta: <span class=\"greek\">κράζω</span> <span class=\"greek\">λέγων</span>, digo em alta voz (Ex 5:8; TestAbr B 6 p. 110, 5 [Stone p. 68]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:29</a>; 14:30; 15:22 (veja <span class=\"greek\">κραυγάζω</span>); 20:30f; 21:9; 27:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:37</a>; 19:12, variante de leitura (em lugar de <span class=\"greek\">ἐκραύγασαν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:18f</a>. Também, pleonasticamente, <span class=\"greek\">κ</span>. <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span> <span class=\"greek\">λέγων</span>, clamo em alta voz e digo, 6:10; 7:10. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span> <span class=\"greek\">λέγων</span>, 19:17; compare 18:2. <span class=\"greek\">κράξας</span> <span class=\"greek\">ἔλεγε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:24</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">λέγειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:27</a>; 21:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:41</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:14f</a>. <span class=\"greek\">ἔκραξεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἶπεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:44</a>. <span class=\"greek\">ἔκραξεν</span> <span class=\"greek\">διδάσκων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λέγων</span>, clamou enquanto ensinava e disse, 7:28. O perfeito <span class=\"greek\">κέκραγα</span> tem sentido de presente (Hippocr., <span class=\"greek\">Περὶ</span> <span class=\"greek\">ἱερ</span>. <span class=\"greek\">νούς</span>. 15 vol. VI 388 Littré <span class=\"greek\">βοᾷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κέκραγεν</span>; Menand., Sam. 226; 239 S. [11; 24 Kö.]; Plut., Cato Min. 58, 1 <span class=\"greek\">μαρτυρόμενος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κεκραγώς</span>; Lucian, Demon. 48 <span class=\"greek\">κεκραγότα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λέγοντα</span>; Ex 5:8; 2 Km 19:29; Is 15:4; Job 30:20, 28; 34:20; Ps 4:4; 140:1): <span class=\"greek\">Ἰωάννης</span> <span class=\"greek\">μαρτυρεῖ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κέκραγεν</span> <span class=\"greek\">λέγων</span>, João testemunha a seu respeito e proclama dizendo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:15</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τινὶ</span> (<span class=\"greek\">ἐν</span>) <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span> (<span class=\"greek\">λέγων</span>), clamar a alguém em alta voz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:2</a>; 14:15.—Dos coros de anjos, 1 Cl 34:6 (Is 6:3).</p>\n<p class=\"entry-text\">ⓑ Figuradamente.</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. Da fala urgente do profeta (Jos., Ant. 10, 117, a respeito de Jeremias) ou do que seu livro diz (Ammonius Herm. em Aristot. Lib. De Interpret. p. 183, 30 Busse: <span class=\"greek\">ἀκουέτω</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀριστοτέλους</span> <span class=\"greek\">κεκραγότος</span> <span class=\"greek\">ὅτι</span> … ; Just., D. 70, 5 <span class=\"greek\">αἱ</span> <span class=\"greek\">γραφαὶ</span> <span class=\"greek\">κεκράγασιν</span>), <span class=\"greek\">Ἠσαί̈ας</span> <span class=\"greek\">κράζει</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰσραήλ</span>, Isaías clama acerca de Israel, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:27</a>. Sobre a oração, mais fervorosa do que audível, 8:15. <span class=\"greek\">ἐκέκραξεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δίκαιος</span>, o justo clamou, 1 Cl 22:7 (Ps 33:18). Do Espírito divino no coração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:6</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. De coisas (Epict 1, 16, 11 <span class=\"greek\">κέκραγεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">φύσις</span>; Achilles Tat. 5, 17, 4 <span class=\"greek\">κέκραγέ</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μορφὴ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">εὐγένειαν</span>): pedras que gritariam se os discípulos se calassem quanto à confissão da condição messiânica de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:40</a>. O salário retido dos trabalhadores <span class=\"greek\">κράζει</span>, clama, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:4</a> (compare Gen 4:10; 18:20; Philo, Ebr. 98 <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἄλογοι</span> <span class=\"greek\">ὁρμαί</span>; Jos., Bell. 1, 197. Sobre o assunto, veja KBerger, Die Gesetzesauslegung Jesu I, ’72, 382–84; outras referências em PvanderHorst, The Sentences of Pseudo-Phocylides ’78, 126).—B. 1250. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραιπάλη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κραιπάλη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (também <span class=\"greek\">κρεπάλη</span>, veja essa entrada; tanto ‘bebedeira, intoxicação’ quanto seu resultado ‘dor de cabeça causada pela embriaguez, ressaca’ estão associados no emprego do termo, visto que significa ‘tontura, cambaleio’ quando a cabeça deixa de funcionar [Aristoph.; Plut., Mor. 127f; Lucian, Bis Accus. 16; Soranus p. 16, 26; Aretaeus p. 110, 2]): entrega desenfreada à bebida numa festa, bebedeira (Aristoph., Ach. 277; Vesp. 1255); <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">μέθῃ</span>, com dissipação e embriaguez, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:34</a> (compare Herodian 2, 6, 6 <span class=\"greek\">παρὰ</span> <span class=\"greek\">μέθην</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κρ</span>.; Is 24:20). <span class=\"greek\">πολυτέλεια</span> <span class=\"greek\">μεθυσμάτων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κραιπαλῶν</span>, extravagância em embriaguez e bebedeiras, Hm 6, 2, 5.—HCadbury, Style 54.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρανίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρανίον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hom. e outros; papiros, LXX; ApcEsdr 5:24 p. 30, 28 Tdf.; Jos., Bell. 3, 245, Ant. 8, 390): crânio, caveira; <span class=\"greek\">κρανίου</span> (genitivo epexegético) <span class=\"greek\">τόπος</span>, o lugar chamado Caveira, como tradução de <span class=\"greek\">Γολγοθᾶ</span> (veja essa entrada), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:17</a>. Compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:33</a>, onde ‘Calvary’, na KJV, não é nome de lugar do NT, mas tradução latina de <span class=\"greek\">κ</span>. (veja Goodsp., Probs. 89f). Escólio a Lucian 251, 20f <span class=\"greek\">Κρανίον</span>· <span class=\"greek\">ἔστι</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Κορίνθῳ</span>; Diog. L. 6, 77 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Κρανείῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Κορίνθου</span> <span class=\"greek\">γυμνασίῳ</span>.—Para outras referências, veja <span class=\"greek\">Γολγοθᾶ</span>.—B. 213f. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράσπεδον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κράσπεδον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (autores trágicos, X. e outros; LXX; empréstimo no hebraico rabínico).</p>\n<p class=\"entry-text\">① Extremidade, borda, bainha de uma vestimenta (Theocr. 2, 53; Appian, Bell. Civ. 1, 16 §68 <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱματίου</span>, da veste do Pontifex Maximus; Ael. Aristid. 47 p. 416 D.; Athen. 4, 49, 159d; 9, 16, 374a; PGM 7, 371 <span class=\"greek\">ἐξάψας</span> <span class=\"greek\">κράσπεδον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱματίου</span> <span class=\"greek\">σου</span>; Zech 8:23): <span class=\"greek\">ἥψατο</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱματίου</span> <span class=\"greek\">αὐτοῦ</span>, tocou na bainha da sua veste, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:44</a> (veja Acta Pilati 7 = ASyn. 95, 90); compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:56</a>.—Mas o sentido 2 também é provável nessas passagens, a depender de quão estritamente Jesus observava a Lei mosaica e de como <span class=\"greek\">κ</span>. era entendido pelos autores e primeiros leitores dos evangelhos.</p>\n<p class=\"entry-text\">② Franja ritual (<span class=\"hebrew\" dir=\"rtl\">צִיצִת</span>) que um israelita devia trazer nas quatro extremidades da veste externa, segundo Num 15:38f; Dt 22:12 (Schürer II 479 [fontes e bibliografia]; Billerb. IV 276–92). Dos fariseus: <span class=\"greek\">μεγαλύνειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>., alongar as franjas das próprias vestes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:5</a>.—B. 859f. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραταιός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κραταιός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (veja o verbete seguinte; em Hom. e outros poetas; na prosa, aparece tardiamente: Philo Mech. 80, 22; Polyb. 2, 69, 8; Cornutus 31 p. 63, 1; Plut., Crass. 24, 4, Mor. p. 967c; Lucian, Anach. 28; Vett. Val. índice; Mitt-Wilck. I/2, 122, 1 [6 d.C.] <span class=\"greek\">τῷ</span> <span class=\"greek\">μεγίστῳ</span> <span class=\"greek\">κραταιῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">Σοκνοπαίῳ</span>; PGM 7, 422 <span class=\"greek\">θεοὶ</span> <span class=\"greek\">κραταιοί</span>; 563; 789; LXX; TestJud 5:1; 6:3; JosAs cap. 11 [códice A 54, 4 Bat. e Pal. 364]; Philo, Spec. Leg. 1, 307 <span class=\"greek\">θεὸς</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἰσχυρὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κραταιός</span>): poderoso, vigoroso, sobre a mão de Deus (frequentemente na LXX; TestJos 1:5; PGM 4, 1279; 1307), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:6</a>; 1 Cl 28:2; 60:3; GJs 15:4; <span class=\"greek\">δύναμις</span>, poder vigoroso (compare Philo, Conf. Lingu. 51), Hv 1, 3, 4.—DELG s.v. <span class=\"greek\">κράτος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραταιόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κραταιόω</span> (‘fortalecer’; derivado de <span class=\"greek\">κραταιός</span>; forma posterior de <span class=\"greek\">κρατύνω</span>. Hippocr.: CMG I 1 p. 88, 12; LXX.—Philo usa a voz média em sentido ativo: Conf. Lingu. 101; 103): imperfeito passivo <span class=\"greek\">ἐκραταιούμην</span>; infinitivo 1º aoristo passivo <span class=\"greek\">κραταιωθῆναι</span>. Em nossa literatura, somente na passiva: tornar-se forte. No sentido físico (Philo, Agr. 160, Omn. Prob. Lib. 27; TestNapht 1:4): com <span class=\"greek\">αὐξάνειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:40</a>, e também GJs 6:1. No sentido psicológico de encorajamento para permanecer firme: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:13</a> (com <span class=\"greek\">ἀνδρίζεσθαι</span>, como Ps 30:25; 2 Km 10:12); <span class=\"greek\">κ</span>. <span class=\"greek\">πνεύματι</span>, crescer em força de espírito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.80\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:80</a>; <span class=\"greek\">δυνάμει</span> <span class=\"greek\">κ</span>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span>, ser vigorosamente fortalecido por meio do Espírito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:16</a>.—DELG s.v. <span class=\"greek\">κράτος</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρατέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρατέω</span>: imperfeito <span class=\"greek\">ἐκράτουν</span>; futuro <span class=\"greek\">κρατήσω</span>; 1º aoristo <span class=\"greek\">ἐκράτησα</span>; perfeito, 1ª pessoa do plural, <span class=\"greek\">κεκρατήκαμεν</span>, 1 Macc 15:33, infinitivo <span class=\"greek\">κεκρατηκέναι</span>; mais-que-perfeito, 3ª pessoa do singular, <span class=\"greek\">κεκρατήκει</span>, 4 Macc 6:32. Na passiva: imperfeito <span class=\"greek\">ἐκρατούμην</span>; futuro, 3ª pessoa do plural, <span class=\"greek\">κρατηθήσονται</span>; aoristo <span class=\"greek\">ἐκρατήθην</span>, Eccl 9:12, variante de leitura; perfeito <span class=\"greek\">κεκράτημαι</span>, 3ª pessoa do plural <span class=\"greek\">κεκράτηνται</span> (desde Hom.). O sentido primordial é exercer poder; por transferência:</p>\n<p class=\"entry-text\">① Realizar algo superando obstáculos, alcançar (Diod S 3, 54, 7 <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπιβολῆς</span>, alcançar o propósito; igualmente 17, 77, 4 e 20, 25, 3; Appian, Bell. Civ. 3, 61 §249 <span class=\"greek\">οὐ</span> … <span class=\"greek\">ἐκράτησε</span>), <span class=\"greek\">τῆς</span> <span class=\"greek\">προθέσεως</span>, o propósito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:13</a> (veja Field, Notes 144).</p>\n<p class=\"entry-text\">② Usar as mãos para estabelecer contato estreito, segurar. ⓐ Segurar <span class=\"greek\">τινά</span>, alguém (firmemente) com a mão (TestAbr A 12 p. 91, 19 [Stone p. 30]), para que a pessoa não consiga afastar-se, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:11</a>. ⓑ Segurar na mão (SibOr 3, 49; TestAbr A 10 p. 87, 29 [Stone p. 22]; A 12 p. 91, 5 [Stone p. 30] e outros; GrBar 11:8), <span class=\"greek\">τὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">δεξιᾷ</span>, alguma coisa na mão direita, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:1</a> (Polemo Perieg. [c. 200 a.C.] em Athen. 11, 67, 484c <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">δεξιᾷ</span> <span class=\"greek\">κώθωνα</span> <span class=\"greek\">κ</span>.; compare Plut., Mor. 99d).</p>\n<p class=\"entry-text\">③ Tomar o controle de alguém ou de algo; agarrar, dominar. ⓐ Quanto a pôr alguém sob custódia: prender, capturar, com <span class=\"greek\">τινά</span>, alguém (compare Ps 136:9; AscIs 3:12), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:3</a>; 21:46; 26:4, 48, 50, 55, 57 (sobre a prisão de Jesus, veja Feigel, Weidel e Finegan s.v. <span class=\"greek\">Ἰούδας</span> 6); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:17</a>; 12:12; 14:1, 44, 46, 49, 51; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:2</a>. ⓑ Quanto a agarrar com força, mas também sem empregar força: tomar, segurar, agarrar (compare 2 Km 6:6; SSol 3:4; TestSol 22:10); com acusativo de pessoa ou coisa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:11</a>; 18:28; 22:6; 28:9; <span class=\"greek\">κρατῆσαι</span> <span class=\"greek\">αὐτόν</span>, dominar (Jesus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:21</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ῥάβδον</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χειρί</span>, segurar um bastão com a mão, Hs 9, 6, 3 (compare PGM 5, 451 <span class=\"greek\">κράτει</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀριστερᾷ</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δακτύλιον</span>; Synes., Ep. 58 p. 202 <span class=\"greek\">πόδα</span>). <span class=\"greek\">τῆς</span> <span class=\"greek\">χειρός</span> (<span class=\"greek\">τινος</span>), segurar a mão (de alguém) (B-D-F §170, 2; Rob. 475; 1391; Ps 72:23; Gen 19:16; JosAs 29:3; ParJer 6:2; Jos., Bell. 1, 352), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:31</a>; 5:41; 9:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:54</a>; B 14:7 (Is 42:6). <span class=\"greek\">τινὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χειρός</span>, tomar alguém pela mão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:27</a>, variante de leitura; compare B 12:11 (Is 45:1).</p>\n<p class=\"entry-text\">④ Sustentar algo erguido ou servir-lhe de fundamento; manter de pé, sustentar, com <span class=\"greek\">τὶ</span>, alguma coisa, Hs 9, 8, 5. <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span>, v 3, 8, 3 (veja MDibelius, Hdb. ad loc.). Na passiva, ser sustentado, <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span>, por alguma coisa, Hv 3, 3, 5. Com <span class=\"greek\">ἀπό</span> em lugar de <span class=\"greek\">ὑπό</span>: <span class=\"greek\">κρατοῦνται</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἀλλήλων</span>, recebem apoio uns dos outros (com ênfase na reciprocidade), 3, 8, 7. Com <span class=\"greek\">διά</span>: <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τεσσάρων</span> <span class=\"greek\">στοιχείων</span> <span class=\"greek\">κρατεῖται</span>, o mundo é sustentado por quatro elementos, 3, 13, 3.</p>\n<p class=\"entry-text\">⑤ Controlar de tal modo que algo não aconteça; deter ou impedir, obstar a uma ação; com acusativo (assim TestJob 35:1), seguido de <span class=\"greek\">ἵνα</span> <span class=\"greek\">μή</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:1</a>. Na passiva: ser impedido, seguido de <span class=\"greek\">τοῦ</span> <span class=\"greek\">μή</span> e infinitivo (TestSol 10:43 C; B-D-F §400, 4; Rob. 1061; 1425), a respeito dos olhos deles: <span class=\"greek\">ἐκρατοῦντο</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐπιγνῶναι</span>, estavam impedidos de reconhecer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:16</a>, provavelmente sugerindo tanto visão física quanto percepção interior (compare 4 Km 6:15–23; veja <span class=\"greek\">διανοίγω</span> 1b).—Manter em seu poder (PTebt 61b, 229; POxy 237 VIII, 34; TestSol 6:3; Jos., C. Ap. 1, 84; Mel., P. 100, 769), na passiva: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">δυνατὸν</span> <span class=\"greek\">κρατεῖσθαι</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτοῦ</span>, era impossível que ele (Cristo) fosse retido por seu poder (da morte), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:24</a>.</p>\n<p class=\"entry-text\">⑥ Aderir firmemente, apegar-se, manter. ⓐ Quanto à dedicação a alguém ou alguma coisa: apegar-se firmemente a alguém ou algo e, por conseguinte, permanecer estreitamente unido. Com acusativo, <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span>, manter-se unido à Cabeça (isto é, a Cristo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:19</a> (compare SSol 3:4 <span class=\"greek\">ἐκράτησα</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀφήσω</span> [<span class=\"greek\">ἀφῆκα</span> BS] <span class=\"greek\">αὐτόν</span>). Com <span class=\"greek\">τί</span>, a alguma coisa (TestNapht 3:1 <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>): <span class=\"greek\">τὴν</span> <span class=\"greek\">παράδοσιν</span>, a tradição, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:3</a>; compare os versículos 4, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:15</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">διδαχήν</span>, a doutrina, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:14f</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομά</span> <span class=\"greek\">μου</span>, o meu nome, v. 13.—Com genitivo de coisa (Stephan. Byz. s.v. <span class=\"greek\">Γυναικόπολις</span>: na ausência dos homens, <span class=\"greek\">τὰς</span> <span class=\"greek\">γυναῖκας</span> <span class=\"greek\">κρατῆσαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πολέμου</span>, as mulheres prosseguiram com a guerra; Pr 14:18; Jos., Ant. 6, 116 <span class=\"greek\">τοῦ</span> <span class=\"greek\">λογισμοῦ</span>), <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁμολογίας</span>, manter-se firme na nossa confissão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:14</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλπίδος</span>, na esperança, 6:18. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">τινός</span>, nas obras de alguém, Hv 3, 8, 8. ⓑ Manter firmemente o que pertence a si mesmo, para que não seja arrebatado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:25</a>; 3:11. ⓒ Guardar para si uma afirmação, com o fim de refletir posteriormente sobre ela, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:10</a>.</p>\n<p class=\"entry-text\">⑦ Fazer uma condição persistir; manter: <span class=\"greek\">κ</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span>, declarar que os pecados não são perdoados (em oposição a <span class=\"greek\">ἀφιέναι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:23</a>.—B. 746. DELG s.v. <span class=\"greek\">κράτος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράτιστος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo superlativo; tratamento honorífico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κράτιστος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Hom. e outros; IBM III/2, 482A, 6 e outros; papiros, LXX, EpArist, Philo, Joseph. Superlativo isolado de <span class=\"greek\">κρατύς</span>, ‘forte, poderoso’): forma honorífica enfática de tratamento, muito nobre, excelentíssimo, usada para dirigir-se a pessoas de posição social variada. Do governador da Judeia (sobre fórmulas de tratamento de funcionários, veja Magie 31; 112; Hahn 259; OSeeck em Pauly-W. V 2006f; OHirschfeld, Kleine Schriften 1913, 651, 5; 654; Wilcken, Her. 20, 1885, 469ff; WSchubart, Einf. in d. Papyruskunde 1918, 259. Compare PHerrmann, Inschriften von Sardeis: Chiron 23, ’93, 236 n. 13.—Jos., Ant. 20, 12; não se pode determinar com certeza se a tradução latina ‘vir egregius’ era aplicada no primeiro século a altos funcionários), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:26</a>; 24:3; 26:25. Como fórmula de tratamento cortês sem conotação oficial (Theophr., Char. 5; Dionys. Hal., De Orat. Ant. 1 <span class=\"greek\">ὦ</span> <span class=\"greek\">κράτιστε</span> <span class=\"greek\">Ἀμμαῖε</span>; Jos., Vi. 430 <span class=\"greek\">κράτιστε</span> <span class=\"greek\">ἀνδρῶν</span> <span class=\"greek\">Ἐπαφρόδιτε</span> [liberto de Domiciano a quem Josefo dedicou suas Antiguidades e os livros contra Apião]; igualmente C. Ap. 1, 1 [mas 2, 1 <span class=\"greek\">τιμιώτατέ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">Ἐ</span>.; 2, 296 usa simplesmente seu nome]. <span class=\"greek\">κ</span>. também ocorre em dedicatórias: Diosc., Mat. Med. I 3, 1f; Hermog., Inv. 3 p. 126, 2f; Artem. 236, 2f P.; Galen X 78; XIV 295; XIX 8 Kühn.—B-D-F §60, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:3</a>; Dg 1:1. Veja Zahn, Einl. II3 340; 365; 390, Ev. des Lk.3, 4 1920, 56f; Cadbury, Making of Luke-Acts 314f; LAlexander, The Preface to Luke’s Gospel ’93 132f; 188–90 (a posição social do destinatário de Lucas continua indeterminada).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κράτος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κράτος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (desde Hom.).</p>\n<p class=\"entry-text\">① Capacidade de manifestar ou expressar força inerente, poder.</p>\n<p class=\"entry-text\">ⓐ Do poder de Deus (Theognis 376 e outros; Ael. Aristid. 37, 8 K. = 2 p. 15D.; 2 Macc 3:34; 7:17; 11:4; veja também 3 abaixo), 1 Cl 33:3; 61:1; 64; AcPl Ha 5, 26. Do poder de Jesus, 2 Cl 17:5.—<span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">αὐτοῦ</span>, seu poder (divino) glorioso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:11</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">κράτος</span> <span class=\"greek\">αὐξάνειν</span>, crescer poderosamente, extraordinariamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:20</a> (<span class=\"greek\">κατὰ</span> <span class=\"greek\">κράτος</span>, como em Menand., Per. 407; Dio Chrys. 26 [43], 11; IG XII/5, 444, 103 [264/263 a.C.]; PTebt 27, 83 [113 a.C.]; AArgyle, ET 75, ’64, 151 relaciona <span class=\"greek\">κατὰ</span> <span class=\"greek\">κ</span>. com <span class=\"greek\">τ</span>. <span class=\"greek\">κυρίου</span>, ‘pelo poder do Senhor’).</p>\n<p class=\"entry-text\">ⓑ Da intensidade do poder (compare Appian, Bell. Civ. 2, 35 §141 <span class=\"greek\">κατὰ</span> <span class=\"greek\">κράτος</span>, com toda a sua força; Ps.-Callisth. 1, 8, 2 <span class=\"greek\">ἡλίου</span> <span class=\"greek\">κ</span>.; Ps 89:11): <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰσχύος</span> <span class=\"greek\">αὐτοῦ</span>, a operação de sua força = força poderosa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:19</a>; 6:10; 1 Cl 27:5 (compare Is 40:26; Da 4:30 Theod.; veja 1QS 11, 19f; 1QH 4, 32).</p>\n<p class=\"entry-text\">② Resultado concreto da força inerente, feito poderoso: <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">κ</span>. (compare <span class=\"hebrew\" dir=\"rtl\">עָשָׂה</span> <span class=\"hebrew\" dir=\"rtl\">חַיִל</span>, Ps 118:15), realizar feitos poderosos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:51</a>.</p>\n<p class=\"entry-text\">③ Exercício da capacidade de governar, poder, domínio, soberania (Arrian, Anab. 4, 20, 3, o poder governante do grande rei; POxy 41 I, 2 <span class=\"greek\">εἰς</span> <span class=\"greek\">αἰῶνα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κράτος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ῥωμαίων</span>; Mel., HE 4, 26, 7 <span class=\"greek\">τὸ</span> <span class=\"greek\">Ῥωμαίων</span> … <span class=\"greek\">κράτος</span>. Sobre divindades: Apollon. Rhod. 4, 804, Zeus; UPZ 81 II, 17 [II a.C.] Ísis: <span class=\"greek\">ἐλθέ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">θεὰ</span> <span class=\"greek\">θεῶν</span>, <span class=\"greek\">κράτος</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">μέγιστον</span>; PSI 29, 21 <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀδωναῖ</span>; POxy 1380, 238 <span class=\"greek\">ἀστραπῶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχεις</span>; Philo, Spec. Leg. 1, 307 <span class=\"greek\">τ</span>. <span class=\"greek\">ὅλων</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>.; Jos., Ant. 10, 263 <span class=\"greek\">τὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχων</span>): <span class=\"greek\">τὸν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχοντα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span>, aquele que tem poder sobre a morte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:14</a> (<span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τινός</span> desde Hdt. 3, 69).—Em doxologias (Mel., P. 105, 823): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:11</a>; 5:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:6</a>; 5:13; 1 Cl 65:2; MPol 20:2.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραυγάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κραυγάζω</span> (veja o verbete seguinte): imperfeito <span class=\"greek\">ἐκραύγαζον</span>; futuro <span class=\"greek\">κραυγάσω</span>; 1º aoristo <span class=\"greek\">ἐκραύγασα</span> (fragmento poético em Pla., Rep. 10 p. 607b [de um cão]; Demosth. 54, 7; Epict 3, 1, 37 [de um corvo]; 3, 4, 4; 2 Esdr 3:13 <span class=\"greek\">λαὸς</span> <span class=\"greek\">ἐκραύγασεν</span> <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span>; TestSol): emitir um som alto, normalmente áspero, gritar, clamar, sendo a natureza da articulação indicada pelo contexto. De sons de animais, como os grunhidos de porcos famintos, B 10:3.—Da voz humana: gritar, pedir socorro, berrar excitadamente (Epict 1, 18, 19; Polemo, Decl. 1, 40 p. 14, 16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:23</a>. Também seguido de <span class=\"greek\">λέγοντες</span>, introduzindo discurso direto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:22</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:40</a>; 19:6, 12 (veja <span class=\"greek\">κράζω</span> 2a). Sem <span class=\"greek\">λέγ</span>. e seguido de discurso direto, v. 15. De um clamor alto em momento de exaltação: <span class=\"greek\">κ</span>. <span class=\"greek\">ὡσαννά</span>, clamar ‘hosana’, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:13</a> (variante de leitura <span class=\"greek\">ἔκραζον</span> + <span class=\"greek\">λέγοντες</span>). <span class=\"greek\">κ</span>. <span class=\"greek\">φωνῇ</span> <span class=\"greek\">μεγάλῃ</span>, com discurso direto subsequente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.43\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:43</a>; IPhld 7:1.—De espíritos possessores que saem das pessoas e falam em línguas humanas: <span class=\"greek\">δαιμόνια</span> <span class=\"greek\">κραυγάζοντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λέγοντα</span> <span class=\"greek\">ὅτι</span>, demônios que gritavam e diziam que, seguido de discurso direto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:41</a> (ao aparato de N., acrescentar P75; sobre a expressão, compare TestSol 1:12 <span class=\"greek\">ἐκραύγασε</span> <span class=\"greek\">λέγων</span>).—B 1250. DELG s.v. <span class=\"greek\">κραυγή</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κραυγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κραυγή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (veja o verbete precedente; Eur., X. e outros; Vett. Val. 2, 35; PPetr II, 45 III, 25 [246 a.C.]; POxy 1242 III, 54; PTebt 15, 3; LXX; En 104:3; PsSol 1:2; TestJob 33:2; EpArist; Joseph.; Ath. 11:1).</p>\n<p class=\"entry-text\">① Grito ou chamado alto, clamor, literalmente.</p>\n<p class=\"entry-text\">ⓐ Gritaria, tumulto de pessoas agitadas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:31</a>. De pessoas que gritam umas contra as outras numa disputa: <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μεγάλη</span>, levantou-se grande clamor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:9</a> (compare Ex 12:30; sem <span class=\"greek\">μεγ</span>. X., Cyr. 7, 5, 28). De pessoas que incitam umas às outras a desfrutar de um espetáculo, AcPl Ha 4, 6.</p>\n<p class=\"entry-text\">ⓑ Um grito alto (articulado): <span class=\"greek\">κ</span>. <span class=\"greek\">γέγονεν</span>, seguido de discurso direto, levantou-se um clamor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:6</a> (EGrässer, D. Problem der Parousieverzögerung, ZNW Beih. 22, ’57, 124f). <span class=\"greek\">ἀνεφώνησεν</span> <span class=\"greek\">κραυγῇ</span> <span class=\"greek\">μεγάλῃ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἶπεν</span>, seguido de discurso direto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:42</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:18</a>, variante de leitura. De oração fervorosa (Ps 17:7; 101:2; Jon 2:3): <span class=\"greek\">μετὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἰσχυρᾶς</span>, com forte clamor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:7</a> (compare Diod S 19, 83, 3 e Ath. 11:1 <span class=\"greek\">μετὰ</span> <span class=\"greek\">πολλῆς</span> <span class=\"greek\">κραυγῆς</span>;—<span class=\"greek\">μετὰ</span> <span class=\"greek\">κ</span>., como Diod S 11, 36, 1; Nicol. Dam.: 90, Fgm. 130, 25 p. 409, 20 Jac.; UPZ 8, 17 [161 a.C.]; EpArist 186; Jos., Bell. 2, 517). <span class=\"greek\">ἀκουσθῆναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">φωνὴν</span> <span class=\"greek\">ὑμῶν</span>, para que vossa voz seja ouvida em clamores altos, B 3:1 (Is 58:4).—<span class=\"greek\">τρία</span> <span class=\"greek\">μυστήρια</span> <span class=\"greek\">κραυγῆς</span>, <span class=\"greek\">ἅτινα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡσυχίᾳ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐπράχθη</span>, três mistérios (a serem) proclamados em alto clamor, os quais Deus realizou em silêncio, IEph 19:1. Os três ‘mistérios’ são a virgindade de Maria, seu parto e a morte de Jesus. Em contraste com a atuação silenciosa de Deus, Inácio parece ter em mente sua proclamação pública em ambiente cultual, como parte do desígnio divino, acompanhada de um grito responsorial de aclamação. Outros interpretam <span class=\"greek\">κ</span>. aqui como a própria proclamação.</p>\n<p class=\"entry-text\">② Clamor de tristeza ou angústia, pranto, lamento (compare Ex 3:7; 11:6; Esth 4:3; Is 65:19; TestJob 33:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:4</a>.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρέας, κρέως</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρέας</span>, <span class=\"greek\">κρέως</span> e, posteriormente, <span class=\"greek\">κρέατος</span> (veja Thumb 96; Meister-hans3-Schw. p. 143 [inscrição ática de 338 a.C. com <span class=\"greek\">κρέατος</span>]; Thackeray 149, 3; Soph., Lex. s.v. <span class=\"greek\">κρέας</span>), <span class=\"greek\">τό</span>: carne (desde Hom.); no plural, <span class=\"greek\">τὰ</span> <span class=\"greek\">κρέα</span> (B-D-F §47, 1; PsSol 8:12; JosAs 10:14; Jos., Ant. 10, 261): <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">κρέα</span>, comer carne (LXX; TestJud 15:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:13</a>; <span class=\"greek\">κρέας</span> (Gen 9:4; Just., D. 126, 6), GEb 308, 32; 34f.—B. 202. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρείσσων</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρείσσων</span>: veja <span class=\"greek\">κρείττων</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0209-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρείττων, ον,</h1><div class=\"entry-meta\"><span>adjetivo comparativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρείττων</span>, <span class=\"greek\">ον</span>, genitivo <span class=\"greek\">ονος</span>, e <span class=\"greek\">κρείσσων</span> (B-D-F §34, 1; W-S. §5, 27c; Mlt-H. 107; JWackernagel, Hellenistica 1907, 12–25; Reinhold 43f; Thackeray 121, 2. A tradição manuscrita oscila, na maioria dos lugares, entre <span class=\"greek\">ττ</span> e <span class=\"greek\">σς</span>. O termo ocorre desde Hom.); em nossa literatura, é sempre um comparativo verdadeiro (compare <span class=\"greek\">κρατύς</span>, mas funciona como comparativo de <span class=\"greek\">ἀγαθός</span>).</p>\n<p class=\"entry-text\">① Relativo à posição elevada; mais destacado, de categoria superior, preferível, melhor (Pind., Hdt. e outros), sobre pessoas: IPhld 9:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:7</a> (em oposição a <span class=\"greek\">ἐλάττων</span>). <span class=\"greek\">τοσούτῳ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">γενόμενος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγγέλων</span>, tendo-se tornado tanto mais superior aos anjos, 1:4 (Jos., Ant. 8, 111 <span class=\"greek\">τ</span>. <span class=\"greek\">ἄλλων</span> … <span class=\"greek\">κρείττονες</span> <span class=\"greek\">γεγόναμεν</span>).—Sobre coisas: 7:19, 22; 8:6; 9:23; 10:34; 11:16, 35; IRo 2:1; IPol 4:3. <span class=\"greek\">χαρίσματα</span>, dons, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:31a</a>, variante de leitura (para a continuação do v. 31b aqui, compare Appian, Mithrid. 60 §247 <span class=\"greek\">ἑτέραν</span> <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">κρείττονα</span>, conhecer outro caminho, melhor). Seguido de genitivo: melhor do que (LXX; TestJob 27:7; Jos., C. Ap. 1, 273; Tat. 20, 1), Dg 2:2. <span class=\"greek\">κρεῖττόν</span> <span class=\"greek\">τι</span>, alguma coisa melhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.40\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:40</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">κρείσσων</span> <span class=\"greek\">ἐστίν</span>, no aspecto em que ele está em melhor situação (que o outro), Dg 10:6. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κρειττόνων</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">χείρω</span> <span class=\"greek\">μετάνοια</span>, mudança de opinião do melhor para o pior, MPol 11:1.</p>\n<p class=\"entry-text\">② Relativo a uma vantagem comparativa de valor.</p>\n<p class=\"entry-text\">ⓐ Como adjetivo: mais útil, mais vantajoso, melhor, <span class=\"greek\">πεπείσμεθα</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>., estamos convencidos de coisas melhores a vosso respeito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:9</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">συνέρχεσθαι</span>, reunir-se para o melhor (em oposição a <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἧσσον</span>; veja <span class=\"greek\">ἥσσων</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:17</a>. Com genitivo, melhor, mais vantajoso que (Artem. 2, 11 p. 98, 24 <span class=\"greek\">κρεῖττον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κακοῦν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> <span class=\"greek\">κακοῦσθαι</span>), 2 Cl 16:4. <span class=\"greek\">κρεῖσσόν</span> <span class=\"greek\">ἐστιν</span>, seguido de infinitivo, é melhor (Sir 33:22 = 30:30 Ziegler; Diod S 12, 16, 2 <span class=\"greek\">κρεῖττον</span> [variante -<span class=\"greek\">σς</span>-] <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἀποθανεῖν</span> <span class=\"greek\">ἢ</span> … <span class=\"greek\">πειρασθῆναι</span>; Demosth., Ep. 2, 21 <span class=\"greek\">εἰ</span> …, <span class=\"greek\">τεθνάναι</span> <span class=\"greek\">με</span> <span class=\"greek\">κρεῖττον</span> <span class=\"greek\">ἦν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:9</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:17</a>. <span class=\"greek\">κρεῖττον</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">αὐτοῖς</span>, seguido de infinitivo, seria melhor para eles, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:21</a> (veja B-D-F §410; Rob. 1084); compare 1 Cl 46:8. Pleonasticamente, <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">κ</span>., realmente muito melhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:23</a>.</p>\n<p class=\"entry-text\">ⓑ Como advérbio: melhor, <span class=\"greek\">κρεῖσσον</span> <span class=\"greek\">ποιεῖν</span>, agir melhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:38</a>. <span class=\"greek\">κρεῖττον</span> <span class=\"greek\">λαλεῖν</span>, falar melhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:24</a> (com <span class=\"greek\">παρά</span> + acusativo, ‘do que’).—DELG s.v. <span class=\"greek\">κράτος</span> 4. M-M. TW.</p></section></article>"};
